// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

/**
 * BaseTip – an on-chain creator tipping protocol on Base.
 *
 *  - Anyone can register a creator profile with a unique handle.
 *  - Supporters tip creators in USDC or ETH and can attach a public message.
 *  - Tips go straight to the creator's wallet; a small platform fee (feeBps) goes to `treasury`.
 *  - Every tip mints a soulbound (non-transferable) ERC-1155 "Supporter" badge.
 *    Badge id = creator id, balance = number of tips the supporter sent to that creator.
 *    Badge metadata and SVG artwork are generated fully on-chain.
 *  - The contract never holds funds.
 */
interface IERC20 {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface IERC1155Receiver {
    function onERC1155Received(address operator, address from, uint256 id, uint256 value, bytes calldata data)
        external
        returns (bytes4);
}

contract BaseTip {
    // ------------------------------------------------------------------ types

    struct Creator {
        address wallet;
        string handle;
        string name;
        string bio;
        uint64 joinedAt;
        uint32 tipCount;
        uint32 supporterCount;
        uint256 totalUsdc;
        uint256 totalEth;
    }

    struct Tip {
        address from;
        uint32 creatorId;
        uint64 time;
        bool isEth;
        uint256 amount;
        string message;
    }

    // ------------------------------------------------------------------ storage

    string public constant name = "BaseTip Supporter Badges";
    string public constant symbol = "TIPBADGE";
    uint16 public constant MAX_FEE_BPS = 500; // 5%
    uint256 public constant MAX_MESSAGE = 280;

    address public immutable usdc;
    address public owner;
    address public treasury;
    uint16 public feeBps;
    bool public paused;

    Creator[] private _creators; // id = index + 1
    mapping(bytes32 => uint256) private _idByHandle;
    mapping(address => uint256) public creatorIdOf;

    Tip[] private _tips;
    mapping(uint256 => uint256[]) private _creatorTips;
    mapping(address => uint256[]) private _sentTips;

    mapping(uint256 => mapping(address => uint256)) private _badges;
    uint256 private _lock = 1;

    // ------------------------------------------------------------------ events

    event CreatorRegistered(uint256 indexed id, address indexed wallet, string handle);
    event ProfileUpdated(uint256 indexed id, string name, string bio);
    event WalletChanged(uint256 indexed id, address indexed oldWallet, address indexed newWallet);
    event Tipped(
        uint256 indexed tipId, uint256 indexed creatorId, address indexed from, bool isEth, uint256 amount, uint256 fee
    );
    event TransferSingle(address indexed operator, address indexed from, address indexed to, uint256 id, uint256 value);
    event FeeChanged(uint16 feeBps);
    event TreasuryChanged(address treasury);
    event PausedChanged(bool paused);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    // ------------------------------------------------------------------ errors

    error NotOwner();
    error ZeroAddress();
    error IsPaused();
    error Reentrancy();
    error AlreadyRegistered();
    error NotRegistered();
    error BadHandle();
    error HandleTaken();
    error TooLong();
    error UnknownCreator();
    error ZeroAmount();
    error SelfTip();
    error PaymentFailed();
    error FeeTooHigh();
    error Soulbound();
    error BadId();

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    modifier whenActive() {
        if (paused) revert IsPaused();
        _;
    }

    modifier nonReentrant() {
        if (_lock != 1) revert Reentrancy();
        _lock = 2;
        _;
        _lock = 1;
    }

    constructor(address usdc_, address owner_, address treasury_, uint16 feeBps_) {
        if (usdc_ == address(0) || owner_ == address(0) || treasury_ == address(0)) revert ZeroAddress();
        if (feeBps_ > MAX_FEE_BPS) revert FeeTooHigh();
        usdc = usdc_;
        owner = owner_;
        treasury = treasury_;
        feeBps = feeBps_;
        emit OwnershipTransferred(address(0), owner_);
        emit TreasuryChanged(treasury_);
        emit FeeChanged(feeBps_);
    }

    // ------------------------------------------------------------------ creators

    function register(string calldata handle, string calldata displayName, string calldata bio)
        external
        whenActive
        returns (uint256 id)
    {
        if (creatorIdOf[msg.sender] != 0) revert AlreadyRegistered();
        _checkHandle(handle);
        bytes32 key = keccak256(bytes(handle));
        if (_idByHandle[key] != 0) revert HandleTaken();
        _checkProfile(displayName, bio);

        _creators.push(
            Creator({
                wallet: msg.sender,
                handle: handle,
                name: displayName,
                bio: bio,
                joinedAt: uint64(block.timestamp),
                tipCount: 0,
                supporterCount: 0,
                totalUsdc: 0,
                totalEth: 0
            })
        );
        id = _creators.length;
        _idByHandle[key] = id;
        creatorIdOf[msg.sender] = id;
        emit CreatorRegistered(id, msg.sender, handle);
        emit ProfileUpdated(id, displayName, bio);
    }

    function updateProfile(string calldata displayName, string calldata bio) external {
        uint256 id = creatorIdOf[msg.sender];
        if (id == 0) revert NotRegistered();
        _checkProfile(displayName, bio);
        Creator storage c = _creators[id - 1];
        c.name = displayName;
        c.bio = bio;
        emit ProfileUpdated(id, displayName, bio);
    }

    /// Moves the creator profile (and future payouts) to a new wallet.
    function changeWallet(address newWallet) external {
        uint256 id = creatorIdOf[msg.sender];
        if (id == 0) revert NotRegistered();
        if (newWallet == address(0)) revert ZeroAddress();
        if (creatorIdOf[newWallet] != 0) revert AlreadyRegistered();
        creatorIdOf[msg.sender] = 0;
        creatorIdOf[newWallet] = id;
        _creators[id - 1].wallet = newWallet;
        emit WalletChanged(id, msg.sender, newWallet);
    }

    // ------------------------------------------------------------------ tipping

    function tipUsdc(uint256 creatorId, uint256 amount, string calldata message)
        external
        whenActive
        nonReentrant
        returns (uint256 tipId)
    {
        if (amount == 0) revert ZeroAmount();
        Creator storage c = _creatorForTip(creatorId, message);
        uint256 fee = (amount * feeBps) / 10_000;
        address wallet = c.wallet;
        c.totalUsdc += amount;
        tipId = _record(creatorId, c, false, amount, fee, message);
        _pull(msg.sender, wallet, amount - fee);
        if (fee != 0) _pull(msg.sender, treasury, fee);
    }

    function tipEth(uint256 creatorId, string calldata message)
        external
        payable
        whenActive
        nonReentrant
        returns (uint256 tipId)
    {
        if (msg.value == 0) revert ZeroAmount();
        Creator storage c = _creatorForTip(creatorId, message);
        uint256 fee = (msg.value * feeBps) / 10_000;
        address wallet = c.wallet;
        c.totalEth += msg.value;
        tipId = _record(creatorId, c, true, msg.value, fee, message);
        _sendEth(wallet, msg.value - fee);
        if (fee != 0) _sendEth(treasury, fee);
    }

    // ------------------------------------------------------------------ views

    function creatorCount() external view returns (uint256) {
        return _creators.length;
    }

    function getCreator(uint256 id) public view returns (Creator memory) {
        if (id == 0 || id > _creators.length) revert UnknownCreator();
        return _creators[id - 1];
    }

    function creatorIdByHandle(string calldata handle) external view returns (uint256) {
        return _idByHandle[keccak256(bytes(handle))];
    }

    /// Creators with ids in [fromId, fromId + limit).
    function getCreators(uint256 fromId, uint256 limit) external view returns (Creator[] memory list) {
        uint256 total = _creators.length;
        if (fromId == 0) fromId = 1;
        if (fromId > total) return new Creator[](0);
        uint256 end = fromId + limit - 1;
        if (end > total) end = total;
        list = new Creator[](end - fromId + 1);
        for (uint256 i = fromId; i <= end; i++) {
            list[i - fromId] = _creators[i - 1];
        }
    }

    function tipCount() external view returns (uint256) {
        return _tips.length;
    }

    function getTip(uint256 tipId) external view returns (Tip memory) {
        if (tipId >= _tips.length) revert BadId();
        return _tips[tipId];
    }

    function creatorTipsLength(uint256 creatorId) external view returns (uint256) {
        return _creatorTips[creatorId].length;
    }

    function getCreatorTips(uint256 creatorId, uint256 offset, uint256 limit)
        external
        view
        returns (uint256[] memory ids, Tip[] memory tips)
    {
        return _page(_creatorTips[creatorId], offset, limit);
    }

    function sentTipsLength(address supporter) external view returns (uint256) {
        return _sentTips[supporter].length;
    }

    function getSentTips(address supporter, uint256 offset, uint256 limit)
        external
        view
        returns (uint256[] memory ids, Tip[] memory tips)
    {
        return _page(_sentTips[supporter], offset, limit);
    }

    // ------------------------------------------------------------------ ERC-1155 (soulbound badges)

    function balanceOf(address account, uint256 id) external view returns (uint256) {
        return _badges[id][account];
    }

    function balanceOfBatch(address[] calldata accounts, uint256[] calldata ids)
        external
        view
        returns (uint256[] memory out)
    {
        if (accounts.length != ids.length) revert BadId();
        out = new uint256[](accounts.length);
        for (uint256 i = 0; i < accounts.length; i++) {
            out[i] = _badges[ids[i]][accounts[i]];
        }
    }

    function isApprovedForAll(address, address) external pure returns (bool) {
        return false;
    }

    function setApprovalForAll(address, bool) external pure {
        revert Soulbound();
    }

    function safeTransferFrom(address, address, uint256, uint256, bytes calldata) external pure {
        revert Soulbound();
    }

    function safeBatchTransferFrom(address, address, uint256[] calldata, uint256[] calldata, bytes calldata)
        external
        pure
    {
        revert Soulbound();
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == 0x01ffc9a7 // ERC-165
            || interfaceId == 0xd9b67a26 // ERC-1155
            || interfaceId == 0x0e89341c; // ERC-1155 metadata URI
    }

    /// Fully on-chain metadata (JSON + SVG) for the supporter badge of creator `id`.
    function uri(uint256 id) external view returns (string memory) {
        Creator memory c = getCreator(id);
        string memory image = string.concat("data:image/svg+xml;base64,", _b64(bytes(badgeSvg(id))));
        string memory json = string.concat(
            '{"name":"Supporter of @',
            c.handle,
            '","description":"Soulbound BaseTip badge for supporting @',
            c.handle,
            ' on Base. The balance shows how many tips you sent.","image":"',
            image,
            '","attributes":[{"trait_type":"Creator","value":"@',
            c.handle,
            '"},{"trait_type":"Supporters","display_type":"number","value":',
            _toString(c.supporterCount),
            '},{"trait_type":"Tips received","display_type":"number","value":',
            _toString(c.tipCount),
            "}]}"
        );
        return string.concat("data:application/json;base64,", _b64(bytes(json)));
    }

    function badgeSvg(uint256 id) public view returns (string memory) {
        Creator memory c = getCreator(id);
        uint256 hue = uint256(keccak256(bytes(c.handle))) % 360;
        string memory h1 = _toString(hue);
        string memory h2 = _toString((hue + 60) % 360);
        return string.concat(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400">',
            '<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="hsl(',
            h1,
            ',80%,45%)"/><stop offset="1" stop-color="hsl(',
            h2,
            ',85%,25%)"/></linearGradient></defs>',
            '<rect width="400" height="400" rx="36" fill="url(#g)"/>',
            '<circle cx="200" cy="160" r="78" fill="none" stroke="#fff" stroke-width="10" opacity=".9"/>',
            '<circle cx="200" cy="160" r="40" fill="#0052ff" stroke="#fff" stroke-width="8"/>',
            _svgText(id, c)
        );
    }

    // ------------------------------------------------------------------ admin

    function setFee(uint16 feeBps_) external onlyOwner {
        if (feeBps_ > MAX_FEE_BPS) revert FeeTooHigh();
        feeBps = feeBps_;
        emit FeeChanged(feeBps_);
    }

    function setTreasury(address treasury_) external onlyOwner {
        if (treasury_ == address(0)) revert ZeroAddress();
        treasury = treasury_;
        emit TreasuryChanged(treasury_);
    }

    function setPaused(bool paused_) external onlyOwner {
        paused = paused_;
        emit PausedChanged(paused_);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    // ------------------------------------------------------------------ internal

    function _creatorForTip(uint256 creatorId, string calldata message) internal view returns (Creator storage c) {
        if (creatorId == 0 || creatorId > _creators.length) revert UnknownCreator();
        if (bytes(message).length > MAX_MESSAGE) revert TooLong();
        c = _creators[creatorId - 1];
        if (c.wallet == msg.sender) revert SelfTip();
    }

    function _record(uint256 creatorId, Creator storage c, bool isEth, uint256 amount, uint256 fee, string calldata message)
        internal
        returns (uint256 tipId)
    {
        tipId = _tips.length;
        _tips.push(
            Tip({
                from: msg.sender,
                creatorId: uint32(creatorId),
                time: uint64(block.timestamp),
                isEth: isEth,
                amount: amount,
                message: message
            })
        );
        _creatorTips[creatorId].push(tipId);
        _sentTips[msg.sender].push(tipId);
        c.tipCount += 1;
        emit Tipped(tipId, creatorId, msg.sender, isEth, amount, fee);
        _mintBadge(creatorId, c);
    }

    function _mintBadge(uint256 id, Creator storage c) internal {
        address to = msg.sender;
        if (to.code.length != 0) {
            // smart-contract wallets get a badge only if they accept ERC-1155 tokens
            try IERC1155Receiver(to).onERC1155Received(to, address(0), id, 1, "") returns (bytes4 r) {
                if (r != IERC1155Receiver.onERC1155Received.selector) return;
            } catch {
                return;
            }
        }
        if (_badges[id][to] == 0) c.supporterCount += 1;
        _badges[id][to] += 1;
        emit TransferSingle(to, address(0), to, id, 1);
    }

    function _pull(address from, address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, bytes memory data) =
            usdc.call(abi.encodeWithSelector(IERC20.transferFrom.selector, from, to, amount));
        if (!ok || (data.length != 0 && !abi.decode(data, (bool)))) revert PaymentFailed();
    }

    function _sendEth(address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok,) = payable(to).call{value: amount}("");
        if (!ok) revert PaymentFailed();
    }

    function _checkHandle(string calldata handle) internal pure {
        bytes memory b = bytes(handle);
        if (b.length < 3 || b.length > 20) revert BadHandle();
        for (uint256 i = 0; i < b.length; i++) {
            bytes1 ch = b[i];
            bool ok = (ch >= 0x61 && ch <= 0x7a) || (ch >= 0x30 && ch <= 0x39) || ch == 0x5f; // a-z 0-9 _
            if (!ok) revert BadHandle();
        }
    }

    function _checkProfile(string calldata displayName, string calldata bio) internal pure {
        if (bytes(displayName).length > 48 || bytes(bio).length > 200) revert TooLong();
    }

    function _page(uint256[] storage list, uint256 offset, uint256 limit)
        internal
        view
        returns (uint256[] memory ids, Tip[] memory tips)
    {
        uint256 len = list.length;
        if (offset >= len) return (new uint256[](0), new Tip[](0));
        uint256 end = offset + limit;
        if (end > len) end = len;
        uint256 n = end - offset;
        ids = new uint256[](n);
        tips = new Tip[](n);
        for (uint256 i = 0; i < n; i++) {
            uint256 tid = list[offset + i];
            ids[i] = tid;
            tips[i] = _tips[tid];
        }
    }

    function _svgText(uint256 id, Creator memory c) internal pure returns (string memory) {
        return string.concat(
            '<text x="200" y="285" text-anchor="middle" font-family="Helvetica,Arial,sans-serif" font-size="22" ',
            'font-weight="700" letter-spacing="6" fill="#fff" opacity=".85">SUPPORTER</text>',
            '<text x="200" y="330" text-anchor="middle" font-family="Helvetica,Arial,sans-serif" font-size="30" ',
            'font-weight="700" fill="#fff">@',
            c.handle,
            '</text><text x="200" y="368" text-anchor="middle" font-family="Helvetica,Arial,sans-serif" ',
            'font-size="15" fill="#fff" opacity=".7">BaseTip #',
            _toString(id),
            " \xc2\xb7 ",
            _toString(c.supporterCount),
            " supporters</text></svg>"
        );
    }

    function _toString(uint256 v) internal pure returns (string memory) {
        if (v == 0) return "0";
        uint256 len;
        for (uint256 t = v; t != 0; t /= 10) len++;
        bytes memory b = new bytes(len);
        while (v != 0) {
            len--;
            b[len] = bytes1(uint8(48 + (v % 10)));
            v /= 10;
        }
        return string(b);
    }

    function _b64(bytes memory data) internal pure returns (string memory) {
        if (data.length == 0) return "";
        bytes memory table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        uint256 outLen = 4 * ((data.length + 2) / 3);
        bytes memory out = new bytes(outLen);
        uint256 j;
        for (uint256 i = 0; i < data.length; i += 3) {
            uint256 a = uint8(data[i]);
            uint256 b = i + 1 < data.length ? uint8(data[i + 1]) : 0;
            uint256 cc = i + 2 < data.length ? uint8(data[i + 2]) : 0;
            uint256 triple = (a << 16) | (b << 8) | cc;
            out[j++] = table[(triple >> 18) & 63];
            out[j++] = table[(triple >> 12) & 63];
            out[j++] = i + 1 < data.length ? table[(triple >> 6) & 63] : bytes1("=");
            out[j++] = i + 2 < data.length ? table[triple & 63] : bytes1("=");
        }
        return string(out);
    }
}
